(window.webpackJsonp=window.webpackJsonp||[]).push([[118],{504:function(v,_,t){"use strict";t.r(_);var e=t(54),r=Object(e.a)({},(function(){var v=this,_=v.$createElement,t=v._self._c||_;return t("ContentSlotsDistributor",{attrs:{"slot-key":v.$parent.slotKey}},[t("h1",{attrs:{id:"企业数据资源相关会计处理暂行规定"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#企业数据资源相关会计处理暂行规定"}},[v._v("#")]),v._v(" 企业数据资源相关会计处理暂行规定")]),v._v(" "),t("p",[v._v("随着我过数字经济和数字政府建设的显著发展及其成效的逐步体现，数据要素日益受到国家的重视。国家及地方陆续制定了数据产业的发展规划和重要举措，财政部发布了《企业数据资源相关会计处理暂行规定》，旨在为企业如何识别、计量、记录及报告数据资源提供具体的操作指引，为会计信息的用户提供更加准确、透明的决策信息。")]),v._v(" "),t("p",[v._v("“数据资源入表”这一术语就取自《暂行规定》，其中的适用范围部分明确了数据资源入表的服务目的："),t("strong",[v._v("企业按照企业会计准则相关规定确认为无形资产或存货等资产类别的数据资源，以及企业合法拥有或控制的、预期会给企业带来经济利益的、但由于不满足企业会计准则相关资产确认条件而未确认为资产的数据资源的相关会计处理")]),v._v("。因此，数据资源入表可以理解为在会计计量专业视角下，企业拥有或控制的数据相关入表行为的专业称谓。")]),v._v(" "),t("p",[v._v("《暂行规定》主要规范了数据资源作为资产的入表条件、会计处理方式、财务报表的列示和披露要求。其中结合会计中关于资产的定义及特点，明确了适用于企业会计准则要求并可确认为相关资产的数据资源。对于未满足资产确认条件的数据资源，也明确了处理方法：")]),v._v(" "),t("ul",[t("li",[v._v("企业按照《企业会计准则第6号--无形资产》相关规定确认为无形资产类别的数据资源。")]),v._v(" "),t("li",[v._v("企业按照《企业会计准则第1号--存货》相关规定确认为存货类别的数据资源。")]),v._v(" "),t("li",[v._v("企业合法拥有或控制的、预期会给企业带来经济效益的、但由于不满足企业会计准则相关资产确认条件而未确认为资产的数据资源。")])]),v._v(" "),t("p",[v._v("《暂行规定》要求企业在按照相关具体准则进行信息披露的同时，采用表格形式提供更详细的信息。还规定企业可以根据实际情况自行决定是否披露数据资源。企业在资产负债表内结合本企业实际情况下设二级科目，分别在“存货”、“无形资产”、“开发支出”项目下增设“数据资源”项目。")]),v._v(" "),t("p",[v._v("数据资源入表的业务模型主要关注数据交易双方的会计处理方式，采用二分法划分为企业内部使用的数据资源相关会计处理原则和企业对外交易的数据资源相关的会计处理原则。")]),v._v(" "),t("table",[t("thead",[t("tr",[t("th",[v._v("业务模型")]),v._v(" "),t("th",[v._v("外购")]),v._v(" "),t("th",[v._v("自行加工和开发")])])]),v._v(" "),t("tbody",[t("tr",[t("td",[v._v("内部使用")]),v._v(" "),t("td",[v._v("确认为外购无形资产的数据资源")]),v._v(" "),t("td",[v._v("确认为自行开发的数据资源无形资产")])]),v._v(" "),t("tr",[t("td",[v._v("外部交易")]),v._v(" "),t("td",[v._v("确认为外购的存货数据资源")]),v._v(" "),t("td",[v._v("确认为自行加工的数据资源存货")])])])]),v._v(" "),t("p",[v._v("在《暂行规定》的正式发布稿中关于数据资产入表的业务模型中，也说明了确认为无形资产的数据资源交易要将无形资产的摊销金额计入当期损益或相关资产成本，同时确认相关收入。未被确认为无形资产的数据资源交易，按照收入准则规定确认相关收入。企业内部数据资源研究开发项目应当计入当期损益，满足无形资产准则有关条件的计入无形资产。日常持有出售的确认为存货，出售需要确认相关收入。")]),v._v(" "),t("p",[v._v("在正式的发布稿中，数据加工形式增加了数据脱敏、清洗，而数据相关方服务支出也增加了数据采集、脱敏，同时还增加了一些相关费用定义，即数据权属鉴证、质量评估、登记结算、安全管理等费用。")]),v._v(" "),t("p",[v._v("在现代企业管理和财务会计实践中，数据资产入表是一项核心工作，若数据尚未处理但有潜在价值，即可视为数据资源，一旦这些数据能产生经济利益流入，他们就能成为数据资产。因此，数据的价值并非由其本身决定，而是根据需求和使用场景而变化，在不同的场景中，同一数据价值可能有所不同，不同的视角下数据资产入表的意义也有所不同。")]),v._v(" "),t("p",[v._v("站在财务的视角，数据资产入表能够准确反映资产价值，这意味着企业开始正式认可并量化其数据资源价值。传统财务报表往往难以完整体现企业在数据领域的投入以及其带来的潜在经济利益，入表这一举措能使企业对自己的海量信息进行科学估值，这不仅提高了财务报表的真实性和完整性，还让投资者能准确的了解企业的真实价值。对于数据密集型企业，充分挖掘数据资源可以增大企业资产规模。资产规模的增大能间接的提高企业信用评级和融资能力。")]),v._v(" "),t("p",[v._v("从资源管理角度来看，将数据资产纳入企业资产管理体系意味着可以更加重视并有效的管理数据的获取、存储、处理、共享与使用，实现数据资源的有效利用。在这个过程中企业可以明确哪些数据资源对财务状况和运营有积极的影响，并科学衡量和合理分配各类资源投入。")]),v._v(" "),t("p",[v._v("从企业管理的角度来分析，通过准确记录数据资源的价值，企业可以获得更可靠的决策支持和 战略规划依据。将数据视为一种可计量、可管理、可增值的资产，有助于在战略层面利用数据洞察，制定精准的经验决策，以更好的应对市场变化。数据资产入表还能使企业能更清晰地了解自身IT建设全貌和分布，从而优化内部流程，提高数据利用效率。通过评估和管理数据质量、生命周期、成本效益可以推动各部门改进业务流程，减少无效的数据处理，实现数据驱动的精细化管理。最后将数据资源纳入会计报告有助于企业更好的识别和评估潜在风险，对数据价值的评估可揭示数据资产的安全性、可用性以及合规性问题，其衍生出的数据治理体系、数据质量控制、权限以及数据生命周期的管理，将帮助管理者有效量化潜在风险。")])])}),[],!1,null,null,null);_.default=r.exports}}]);